import surf as surfimport surf_analysis as surfAimport surf_inputs as surfINimport surf_insitu as surfISimport numpy as npimport osimport astropy.units as uimport pandas as pdfrom datetime import datetime, timedeltafrom astropy.time import Timeimport refrom sunpy.coordinates import sunimport helio_coords as hcoordsimport matplotlib.animation as animationimport matplotlib.pyplot as pltimport matplotlib as mpl# Function to convert a date string to a datetime objectdef convert_to_datetime(date_str):    # List of possible date formats    date_formats = [        '%Y-%m-%d %H:%M:%S',        '%Y/%m/%d %H%M',        '%Y/%m/%d %H%M(%S)',        '%Y/%m/%d %H%M(S)',        '%Y/%m/%d %H:%M',        '%Y/%m/%d %H:%M:%S',        '%Y/%m/%d %H:%M(S)',        '%d/%m/%Y %H:%M'    ]    for date_format in date_formats:        try:            return datetime.strptime(date_str, date_format)        except ValueError:            continue    # If no format matches, return None    return None    # Function to convert Time_Error from string to timedeltadef convert_to_timedelta(time_str):    try:        return pd.to_timedelta(time_str)    except ValueError:        return None# Function to get earth's latitudedef get_earth_lat(dt):    """    A function to return Earth latitude for a given date, in radians     Parameters    ----------    dt : datetime     Returns    -------    E_lat: Earth latitude, with astropy units of radians     """    cr, cr_lon_init = surfIN.datetime2surfinputs(dt)        # Use the HUXt ephemeris data to get Earth lat over the CR    # ========================================================    dummymodel = surf.SURF(v_boundary=np.ones(128)*400*(u.km/u.s), simtime=0.1*u.day,                         cr_num=cr,cr_lon_init=cr_lon_init, lon_out=0.0*u.deg)    # retrieve a bodies position at each model timestep:    earth = dummymodel.get_observer('earth')    # get average Earth lat    E_lat = np.nanmean(earth.lat_c)    E_lat = E_lat.to(u.deg)  # Convert to degrees    return E_latdef earth_R(mjd):    #returns the heliocentric distance of Earth (in km). Based on Franz+Harper2002    AU = 149597870.691        #first up, switch to JD.    JD=mjd+2400000.5    d0=JD-2451545    T0=d0/36525    L2=100.4664568 + 35999.3728565*T0    g2=L2-(102.9373481+0.3225654*T0)    g2=g2*np.pi/180 #mean anomaly    rAU=1.00014 - 0.01671*np.cos(g2)-0.00014*np.cos(2*g2);    R=rAU*AU        return Rdef calculate_bg_mae(bg_model, onecme, tolerance=pd.Timedelta(minutes=30)):    """    Calculate the Mean Absolute Error between the HUXt background    solar wind speed and OMNI solar wind speed, excluding ICME    periods.    """        # Get HUXt background time series at Earth        bg_ts = surfA.get_observer_timeseries(bg_model, observer='Earth')        bg = bg_ts[['time', 'vsw']].copy()    bg.rename(        columns={            'time': 'datetime',            'vsw': 'V_bg'        },        inplace=True    )    bg['datetime'] = pd.to_datetime(bg['datetime'])    # Define period of interest        starttime = onecme['Time_21.5']    endtime = starttime + timedelta(days=27.0)    # Download OMNI        data = surfIS.get_omni(starttime, endtime)        # Remove ICMEs    omni_noicmes = surfIS.removeICMEs(        data,        interp_gaps=False)            # Keep only the columns needed    obs = omni_noicmes[['datetime', 'V']].copy()        obs.rename(columns={'V': 'V_omni'}, inplace=True)    obs.sort_values('datetime', inplace=True)    bg.sort_values('datetime', inplace=True)        # Match each HUXt time to the nearest OMNI measurement    comparison = pd.merge_asof(        bg,        obs,        on='datetime',        direction='nearest',        tolerance=tolerance)        # Only retain points where both datasets are valid    valid = (comparison['V_bg'].notna() &        comparison['V_omni'].notna())            # Calculate absolute error    comparison['absolute_error'] = np.nan    comparison.loc[valid, 'absolute_error'] = (        np.abs(            comparison.loc[valid, 'V_bg'] -            comparison.loc[valid, 'V_omni']        )    )    # Calculate MAE    mae = comparison['absolute_error'].mean()    return mae, comparison# Read in Met Office Cone CME filesproject_dirs = surf._setup_dirs_()crpath = os.path.join(project_dirs['input'],'(I)CMEs.csv')# Load the CSV file into a DataFramecrlist = pd.read_csv(crpath)# Convert date columns to datetime objects using datetime librarydate_columns = ['Time_21.5', 'Disturbance_Time']for column in date_columns:    crlist[column] = crlist[column].apply(lambda x: convert_to_datetime(x) if isinstance(x, str) else None)# compute 21.5-215 transit time#crlist['tt_21'] = np.nan for irow in range(0, len(crlist)):    crlist.loc[irow,'tt_21'] = crlist.loc[irow,'Disturbance_Time'] - crlist.loc[irow,'Time_21.5']# Convert  from timedelta to dayscrlist['tt_21'] = crlist['tt_21'].apply(lambda x: x.days + x.seconds / 86400 if isinstance(x, timedelta) else None)# Add a new column with carrington rotation number of CME timecrlist['cr_num'] = crlist['Time_21.5'].apply(lambda dt: surfIN.datetime2surfinputs(dt)[0])crlist['cr_lon_init'] = crlist['Time_21.5'].apply(lambda dt: surfIN.datetime2surfinputs(dt)[1])crlist['earth_lat'] = crlist['Time_21.5'].apply(lambda dt: get_earth_lat(dt))mae_results = []# Iterate over all CMEs in crlistfor _, onecme in crlist.iterrows():    try:            ftime = onecme['Time_21.5']        #bg_model = surfIS.omniSURF_reconstruction(ftime, ftime +timedelta(days=27),                                                  #rmin=21.5*u.solRad, rmax=250*u.solRad,                                                  #dt_scale=4, dt=1*u.day,                                                  #run_2d=False,                                                  #solver='huxt')                                                          #bg_model = surfIS.omniSURF_forecast(ftime,                                               #rmin=21.5*u.solRad, rmax=250*u.solRad,                                               #dt_scale=4,                                               #run_2d=False,                                               #solver='huxt')                                                       # Setup HUXt for a standard 30Rs run        #vr_in = surfIN.get_MAS_long_profile(onecme['cr_num'], onecme['earth_lat'])        #  Map the inner boundary MAS values inwards from 30 rS to 21.5 rS        #vr_21 = surfIN.map_v_boundary_inwards(vr_in, 30*u.solRad, 21.5*u.solRad)        #  Now setup HUXt to run from 10Rs        #bg_model = surf.SURF(v_boundary = vr_21,                            #cr_num=onecme['cr_num'],                            #cr_lon_init=onecme['cr_lon_init'],                            #simtime=27.0 * u.day,                            #latitude=0*u.deg,                            #dt_scale=4,                            #r_min = 21.5*u.solRad,                            #r_max = 250*u.solRad,                            #frame = 'synodic',                            #track_cmes = False,                            #lon_out = 0*u.rad)                                    # Obtain WSA boundary conditions at 21.5 rS                date = onecme['Time_21.5']        date_str = date.strftime("%Y%m%d") + "00"                wsafilepath = os.path.join(os.path.join("/Users/dven/repos/Pulse_duration/surf/data/input", "wsa_gong_{}.fits".format(date_str)))        v_wsa = surfIN.get_WSA_long_profile(wsafilepath, lat=0.0 * u.deg)        vr_in = surfIN.map_v_boundary_inwards(v_wsa, 30*u.solRad, 21.5*u.solRad)                cr, cr_lon_init = surfIN.datetime2surfinputs(date)                bg_model = surf.SURF(v_boundary=vr_in, cr_num=cr, cr_lon_init = cr_lon_init,simtime = 27.0 * u.day, r_min=21.5*u.solRad, r_max=250*u.solRad, dt_scale=4, latitude=0*u.deg, frame = 'synodic', track_cmes = False, lon_out = 0*u.rad)        bg_model.solve([])                mae, comparison = calculate_bg_mae(bg_model,onecme)                mae_results.append({            'Time_21.5': onecme['Time_21.5'],            'MAE': mae        })        print(f"MAE = {mae:.2f} km/s")            except Exception as e:        print(f"ERROR in CME {onecme['Time_21.5']}: {e}")        print("Skipping to next CME...")        continue    mae_df = pd.DataFrame(mae_results)out_path = project_dirs['figures']mae_df.to_csv(    os.path.join(out_path, 'MAE_WSA.csv'),    index=False)